package app.lensdrop.transfer;
import android.content.*;import android.database.Cursor;import org.json.*;import java.nio.file.*;import java.util.*;
import static app.lensdrop.transfer.WatchLedgerIntegrationTest.*;
public final class ArchiveWorkflowTest{
 static int total=0;interface Case{void run(Fixture f)throws Exception;}
 static void run(String name,Case c)throws Exception{try(Fixture f=new Fixture()){c.run(f);total++;System.out.println("PASS "+name);}}
 static String scalar(Fixture f,String col,String job){try(Cursor c=f.q.getReadableDatabase().rawQuery("SELECT "+col+" FROM jobs WHERE id=?",new String[]{job})){c.moveToFirst();return c.getString(0);}}
 static void uploaded(Fixture f,String j){f.q.getWritableDatabase().execSQL("UPDATE jobs SET state='uploaded',photo_id=?,sha=? WHERE id=?",new Object[]{UUID.randomUUID().toString(),"a".repeat(64),j});}
 static String group(Fixture f)throws Exception{f.pool("group");return f.w.nextGroup(S);}
 static String fresh(Fixture f,String uri)throws Exception{f.baseline(0);f.q.archivePolicy(S,true);return f.incoming(uri,false);}
 static JSONObject spec(Path file,String id)throws Exception{byte[] data=Files.readAllBytes(file);return new JSONObject().put("id",id).put("bytes",data.length).put("sha256",CloudApi.hex(java.security.MessageDigest.getInstance("SHA-256").digest(data)));}
 public static void main(String[] args)throws Exception{
 run("Enable archive-all promotes existing NEW candidates without guest assignment",f->{f.baseline(2);String j=f.incoming("content://a",false);eq(f.q.jobState(S,j),"candidate");f.q.archivePolicy(S,true);eq(f.q.jobState(S,j),"queued");yes(f.q.due(S).archivePrivate);eq(f.delivery(j),null);eq(f.w.candidates(S,0).length(),1);eq(f.count("SELECT count(*) FROM jobs"),1L);});
 run("Old baseline files stay excluded when archive-all enabled",f->{f.baseline(1000);f.q.archivePolicy(S,true);f.w.arrival(S,"content://image/old-0","old.jpg",999,9,false,false);eq(f.count("SELECT count(*) FROM jobs"),0L);f.restart();yes(f.q.archiveAll(S));eq(f.w.summary(S).optLong("excluded"),1000L);});
 run("New completed arrival archives even with no active guest",f->{String j=fresh(f,"content://new");eq(f.q.due(S).id,j);eq(f.delivery(j),null);eq(f.w.active(S),null);});
 run("Recovered arrival archives without guessing a guest",f->{f.baseline(0);f.q.archivePolicy(S,true);group(f);f.w.auto(S,true);String j=f.incoming("content://later",true);eq(f.q.jobState(S,j),"queued");eq(f.delivery(j),null);});
 run("Archive selection during upload does not reset byte offset or upload state",f->{String j=fresh(f,"content://a");String g=group(f);f.q.getWritableDatabase().execSQL("UPDATE jobs SET state='uploading',offset=64 WHERE id=?",new Object[]{j});eq(f.w.select(S,j),g);eq(f.q.jobState(S,j),"uploading");eq(scalar(f,"offset",j),"64");});
 run("Archived receipt remains uploaded when selected after completion",f->{String j=fresh(f,"content://a");uploaded(f,j);String g=group(f);eq(f.w.select(S,j),g);eq(f.q.jobState(S,j),"uploaded");eq(scalar(f,"delivery_synced",j),"0");yes(f.q.due(S)==null);});
 run("History QR stays visible while a different guest receives archived selection",f->{String j=fresh(f,"content://a");f.pool("group");String a=f.w.nextGroup(S),b=f.w.nextGroup(S);f.w.show(S,a);uploaded(f,j);eq(f.w.select(S,j),b);eq(f.w.shown(S),a);});
 run("Single-photo QR receives only selected archive while other photos still upload",f->{String a=fresh(f,"content://a"),b=f.incoming("content://b",false);f.pool("single");f.w.mode(S,"single");String g=f.w.select(S,a);eq(f.delivery(a),g);eq(f.delivery(b),null);eq(f.q.jobState(S,b),"queued");eq(f.w.candidates(S,0).length(),1);});
 run("Hide from selection does not skip or cancel archive",f->{String j=fresh(f,"content://a");f.w.skip(S,j);eq(f.q.jobState(S,j),"queued");eq(f.w.candidates(S,0).length(),0);yes(f.q.due(S)!=null);throwsIt(()->{try{f.w.select(S,j);}catch(RuntimeException e){throw e;}catch(Exception e){throw new RuntimeException(e);}});});
 run("Hide all unassigned selections retains all upload jobs",f->{String a=fresh(f,"content://a"),b=f.incoming("content://b",false);f.w.skip(S,null);eq(f.w.candidates(S,0).length(),0);eq(f.q.jobState(S,a),"queued");eq(f.q.jobState(S,b),"queued");});
 run("Explicit earlier skips are NOT promoted by archive-all",f->{f.baseline(0);String j=f.incoming("content://skip",false);f.w.skip(S,j);f.q.archivePolicy(S,true);eq(f.q.jobState(S,j),"skipped");yes(f.q.due(S)==null);});
 run("Turning archive-all off changes future arrivals not existing queued work",f->{String a=fresh(f,"content://a");f.q.archivePolicy(S,false);String b=f.incoming("content://b",false);eq(f.q.jobState(S,a),"queued");eq(f.q.jobState(S,b),"candidate");yes(f.q.due(S).archivePrivate);});
 run("Unassigned complete archives permit event turnover without deleting them",f->{String j=fresh(f,"content://a");uploaded(f,j);yes(!f.q.hasOtherPending("next"));eq(f.w.candidates(S,0).length(),1);});
 run("Guest link pending blocks event replacement until synced or explicitly retired",f->{String j=fresh(f,"content://a");uploaded(f,j);group(f);f.w.select(S,j);yes(f.q.hasOtherPending("next"));RecoveryLedger.retireUpload(f.q,S,j);eq(f.q.jobState(S,j),"uploaded");eq(scalar(f,"delivery_synced",j),"-1");yes(!f.q.hasOtherPending("next"));yes(f.delivery(j)!=null);});
 run("Guest-sync error retry is explicit and scoped",f->{String j=fresh(f,"content://a");uploaded(f,j);group(f);f.w.select(S,j);f.q.getWritableDatabase().execSQL("UPDATE jobs SET delivery_error='delivery_owner_mismatch',delivery_next=?,delivery_attempts=3 WHERE id=?",new Object[]{Long.MAX_VALUE,j});f.q.retryAssignments("other");eq(scalar(f,"delivery_attempts",j),"3");f.q.retryAssignments(S);eq(scalar(f,"delivery_next",j),"0");eq(scalar(f,"delivery_attempts",j),"0");});
 run("Assigned archive identity survives reboot and cannot rebind",f->{String j=fresh(f,"content://a");String g=group(f);f.w.select(S,j);f.restart();eq(f.delivery(j),g);eq(f.q.due(S).delivery,g);try{f.w.select(S,j);throw new AssertionError("rebound");}catch(IllegalStateException expected){}});
 run("Malformed source can block its archive while other new photos remain due",f->{String a=fresh(f,"content://a"),b=f.incoming("content://b",false);f.q.state(a,"blocked","jpeg_incomplete",5,0);eq(f.q.due(S).id,b);eq(f.w.candidates(S,0).length(),2);});
 run("Staged edited revision has no guest but archives under archive-all",f->{String j=fresh(f,"content://a");group(f);f.w.select(S,j);uploaded(f,j);String id=UUID.randomUUID().toString();RecoveryLedger.replacement(f.q,S,j,"new.jpg",140,22,"b".repeat(64),"retained-staging",id);eq(f.q.jobState(S,id),"queued");eq(f.delivery(id),null);yes(f.delivery(j)!=null);});
 run("Receipt and unassigned/archive counts remain separate",f->{String j=fresh(f,"content://a");uploaded(f,j);JSONObject p=f.q.snapshot(S).getJSONObject("production");eq(p.getLong("uploaded"),1L);eq(p.getLong("unassigned_archives"),1L);eq(p.getLong("candidates"),0L);});
 run("Preflight job does not become private event archive",f->{f.baseline(0);f.q.archivePolicy(S,true);String j=f.q.addTest(S,"content://test","test.jpg",100,1);yes(!f.q.testDue(S,j).archivePrivate);});
 run("Print capture first commits an independent exact cloud archive",f->{f.baseline(0);Path original=f.dir.resolve("print.jpg");Files.write(original,new byte[]{(byte)255,(byte)216,0,(byte)255,(byte)217});JSONObject spec=spec(original,UUID.randomUUID().toString());String j=ArchiveStaging.register(new Context(f.dir.toString()),S,original.toFile(),spec,null);eq(f.q.jobState(S,j),"queued");eq(f.delivery(j),null);yes(Files.readAllBytes(Path.of(scalar(f,"spool",j))).length==5);Files.delete(original);yes(Files.exists(Path.of(scalar(f,"spool",j))));});
 run("Identical confirmed JPEG reuses private archive instead of duplicate upload",f->{f.baseline(0);Path original=f.dir.resolve("print.jpg");Files.write(original,new byte[]{1,2,3,4});JSONObject spec=spec(original,UUID.randomUUID().toString());String a=ArchiveStaging.register(new Context(f.dir.toString()),S,original.toFile(),spec,null);String b=ArchiveStaging.register(new Context(f.dir.toString()),S,original.toFile(),spec(original,UUID.randomUUID().toString()),null);eq(a,b);eq(f.count("SELECT count(*) FROM jobs"),1L);});
 run("Print snapshot checksum mismatch creates no archive or guest assignment",f->{f.baseline(0);Path original=f.dir.resolve("print.jpg");Files.write(original,new byte[]{1,2,3,4});JSONObject bad=spec(original,UUID.randomUUID().toString()).put("sha256","0".repeat(64));try{ArchiveStaging.register(new Context(f.dir.toString()),S,original.toFile(),bad,null);throw new AssertionError("accepted changed print");}catch(java.io.IOException expected){}eq(f.count("SELECT count(*) FROM jobs"),0L);});
 run("Print photo guest binding is explicit and preserves other assigned guest",f->{f.baseline(0);f.pool("group");String a=f.w.nextGroup(S),b=f.w.nextGroup(S);Path file=f.dir.resolve("print.jpg");Files.write(file,new byte[]{1,2,3,4});JSONObject spec=spec(file,UUID.randomUUID().toString());String j=ArchiveStaging.register(new Context(f.dir.toString()),S,file.toFile(),spec,a);eq(f.delivery(j),a);try{ArchiveStaging.register(new Context(f.dir.toString()),S,file.toFile(),spec,b);throw new AssertionError("wrong guest accepted");}catch(IllegalStateException expected){}eq(f.delivery(j),a);});
 run("Legacy exact-photo assignment also blocks a different guest on new print",f->{f.baseline(0);f.pool("group");String a=f.w.nextGroup(S),j=f.incoming("content://legacy",false);f.w.select(S,j);String b=f.w.nextGroup(S);Path file=f.dir.resolve("print.jpg");Files.write(file,new byte[120]);JSONObject spec=spec(file,UUID.randomUUID().toString());f.q.getWritableDatabase().execSQL("UPDATE jobs SET sha=? WHERE id=?",new Object[]{spec.getString("sha256"),j});try{ArchiveStaging.register(new Context(f.dir.toString()),S,file.toFile(),spec,b);throw new AssertionError("legacy guest replaced");}catch(IllegalStateException expected){}eq(f.count("SELECT count(*) FROM jobs"),1L);eq(f.delivery(j),a);});
 run("PrintQueue saves archive correlation atomically with immutable print request",f->{try(PrintQueue p=new PrintQueue(new Context(f.dir.toString()))){String id=UUID.randomUUID().toString(),archive=UUID.randomUUID().toString();p.add(S,new JSONObject().put("id",id),"snapshot","hybrid",archive);eq(p.next(S).getString("archive_job_id"),archive);p.close();try(PrintQueue again=new PrintQueue(new Context(f.dir.toString()))){eq(again.history(S,0).getJSONObject(0).getString("archive_job_id"),archive);}}});
 run("Exact H5.4 photo schema5 migrates to H5.12.1 schema10 without auto-archiving existing candidates",f->{Path dir=Files.createTempDirectory("h54-photo-upgrade-");try{Context c=new Context(dir.toString());String j;try(FrozenH54QueueDb old=new FrozenH54QueueDb(c)){old.add(S,"content://old","OLD.JPG",120,20);try(Cursor row=old.getReadableDatabase().rawQuery("SELECT id FROM jobs",null)){row.moveToFirst();j=row.getString(0);}old.state(j,"candidate","",0,0);}try(QueueDb now=new QueueDb(c)){eq(now.jobState(S,j),"candidate");yes(!now.archiveAll(S));try(Cursor row=now.getReadableDatabase().rawQuery("PRAGMA user_version",null)){row.moveToFirst();eq(row.getInt(0),10);}}}finally{try(var stream=Files.walk(dir)){for(Path x:stream.sorted(Comparator.reverseOrder()).toList())Files.delete(x);}}});
 run("Exact H5.4 print schema2 migration preserves pending route and no fake archive",f->{Path dir=Files.createTempDirectory("h54-print-upgrade-");try{Context c=new Context(dir.toString());String id=UUID.randomUUID().toString();try(FrozenH54PrintQueue old=new FrozenH54PrintQueue(c)){old.add(S,new JSONObject().put("id",id),"old-staged-image","local");}try(PrintQueue now=new PrintQueue(c)){JSONObject row=now.history(S,0).getJSONObject(0);eq(row.getString("mode"),"local");yes(row.optString("archive_job_id").isEmpty());}}finally{try(var stream=Files.walk(dir)){for(Path x:stream.sorted(Comparator.reverseOrder()).toList())Files.delete(x);}}});
 System.out.println("PASSED "+total+" archive / selection / print-correlation cases. JVM + SQLite bridge, not Android SDK, ContentResolver or device tests.");
 }
}
